sql:
SELECT LastEditDate, LastEditorUserId
FROM posts
WHERE Title = 'Detecting a given face in a database of facial images';

SELECT country
FROM circuits
WHERE alt = (SELECT MAX(alt) FROM circuits);

SELECT Text
FROM comments
WHERE CreationDate = '2010-07-19 19:25:47.0';

SELECT player_api_id
FROM Player_Attributes
WHERE overall_rating = (SELECT MAX(overall_rating) FROM Player_Attributes);

SELECT Id
FROM users
WHERE Reputation = (SELECT MAX(Reputation) FROM users);

SELECT COUNT(DISTINCT PostId)
FROM votes
WHERE BountyAmount >= 30;

SELECT COUNT(*) AS major_count
FROM major
WHERE college = 'College of Humanities and Social Sciences';

SELECT manaCost
FROM cards
WHERE name = 'Ancestor`s Chosen';

SELECT Id AS PostId, OwnerUserId AS UserId
FROM posts
WHERE Score > 60;

SELECT name
FROM cards
WHERE artist = 'Aaron Boyd';

SELECT COUNT(*) AS carcinogenic_compounds
FROM molecule
WHERE label = '+';

SELECT id
FROM superpower
WHERE LOWER(power_name) = 'cryokinesis';

SELECT COUNT(*) AS total_atoms
FROM atom
WHERE element IN ('c', 'h');

SELECT event_id, location, status
FROM event
WHERE event_date BETWEEN '2019-11-01' AND '2020-03-31';

SELECT A3 AS branch_location, A2 AS district_name
FROM district
WHERE A13 = (SELECT MAX(A13) FROM district);

SELECT molecule_id
FROM molecule
WHERE label = '-';

SELECT first_name || ' ' || last_name AS full_name, email
FROM member
WHERE position = 'Secretary';

SELECT code
FROM sets
WHERE type = 'expansion';

SELECT DisplayName, Age
FROM users
WHERE Views = (SELECT MAX(Views) FROM users);

SELECT atom_id, atom_id2
FROM connected
WHERE bond_id = 'TR000_2_5';

SELECT name
FROM cards
WHERE isTextless = 0;

SELECT DISTINCT c.bond_id
FROM connected AS c
WHERE c.atom_id2 = 'TR000_2';

SELECT Age
FROM users
WHERE Reputation = (SELECT MAX(Reputation) FROM users);

SELECT availability
FROM cards
WHERE artist = 'Daren Bader';

SELECT 100.0 * SUM(CASE WHEN isOnlineOnly = 1 THEN 1 ELSE 0 END) / COUNT(id) AS percentage
FROM cards
WHERE frameEffects = 'legendary';

SELECT 100.0 * SUM(CASE WHEN s.gender_id = 2 THEN 1 ELSE 0 END) / COUNT(*) AS percentage_female
FROM superhero AS s
WHERE s.alignment_id = 2;

SELECT element
FROM atom
WHERE atom_id = 'TR000_1';

SELECT Id
FROM users
WHERE Views = (SELECT MIN(Views) FROM users);

SELECT COUNT(*)
FROM Player
WHERE CAST(strftime('%Y', birthday) AS INTEGER) > 1990;
